        grp = df[df[seg_col].isin(top_groups)].groupby(seg_col)[metric_col]
        if agg == 'mean':
            agg_result = grp.mean()
        elif agg == 'sum':
            agg_result = grp.sum()
        elif agg == 'count':
            agg_result = grp.count()

        result['segments'].append({
            'segment_column': seg_col,
            'metric_column': metric_col,
            'aggregation': agg,
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in agg_result.items()]
        })

    count_result = df[df[seg_col].isin(top_groups)].groupby(seg_col)[seg_col].count()
    result['segments'].append({
        'segment_column': seg_col,
        'metric_column': seg_col,
        'aggregation': 'count',
        'results': [{'name': str(k), 'value': float(v)} for k, v in count_result.items()]
    })

